/**
 * LGS okul tarama verisi.
 *
 * Amaç: öğrencinin hedef koyabilmesi. Bu yüzden burada tek bir uydurma sayı
 * bulunmaz — her puan en az bir bağımsız kaynakta doğrulandı, doğrulanamayan
 * alan `null` bırakıldı ve arayüzde "—" olarak gösterilir.
 *
 * Veri toplanırken bulunan önemli hata: yaygın "en iyi 100 lise" listelerinin
 * çoğunda 2025 yüzdelik dilim sütunu aslında 2024'ün değerlerini taşıyor.
 * Beş ayrı araştırma bunu bağımsız olarak tespit etti (doğrulanan 2025
 * yüzdelikleri taban puanına göre monoton artıyor, hatalı olanlar rastgele
 * dalgalanıyor). Buradaki değerler düzeltilmiş hâlleridir.
 *
 * Kimliği doğrulanamayan kayıtlar listeye hiç alınmadı.
 *
 * 2. tur (Ağustos 2026): liste il bazlı araştırmayla 248 okula çıkarıldı
 * (2025 tabanı 440+ bandı, 57 il). Aynı doğrulama disiplini: 6 paralel
 * araştırma, her puan en az iki bağımsız kaynakta; il listelerinin
 * atladığı imam hatip/MTAL programları ayrıca tarandı.
 *
 * Kaynaklar: İl Millî Eğitim Müdürlüklerinin resmî LGS portalları ve okulların
 * kendi meb.k12.tr siteleri birinci derece kaynak; toplayıcı siteler yalnızca
 * çapraz doğrulama için kullanıldı. Her kaydın `kaynaklar` alanı denetlenebilir.
 */

export type OkulTuru =
  | "fen"
  | "anadolu"
  | "sosyal-bilimler"
  | "imam-hatip"
  | "meslek"
  | "proje";

export type YilVerisi = {
  /** En düşük yerleşen puan. */
  taban: number | null;
  /** En yüksek yerleşen puan — kaynakların çoğunda yok. */
  tavan: number | null;
  /** Türkiye geneli yüzdelik dilim (0.61 = %0,61). */
  yuzdelik: number | null;
  kontenjan: number | null;
};

export type Okul = {
  id: string;
  ad: string;
  /** Aynı okulun ayrı programı (Almanca, İngilizce, Siber Güvenlik...). */
  program: string | null;
  il: string;
  ilce: string | null;
  tur: OkulTuru;
  yabanciDil: string | null;
  hazirlik: boolean;
  /** Okulun kendi resmî sitesi. */
  site: string;
  /** 2025 verisi bağımsız ikinci kaynakta doğrulandı mı? */
  dogrulandi: boolean;
  /** Kaynaklar arasında kapanmamış çelişki varsa açıklaması. */
  not?: string;
  puanlar: Record<string, YilVerisi>;
  kaynaklar: string[];
};

export const OKUL_TURU_ADI: Record<OkulTuru, string> = {
  fen: "Fen Lisesi",
  anadolu: "Anadolu Lisesi",
  "sosyal-bilimler": "Sosyal Bilimler Lisesi",
  "imam-hatip": "Anadolu İmam Hatip Lisesi",
  meslek: "Mesleki ve Teknik Anadolu Lisesi",
  proje: "Proje Okulu",
};

/** Verinin hangi tarihte toplandığı — arayüzde gösterilir. */
export const VERI_TARIHI = "Ağustos 2026";

