/** Görüntülenecek ad: program varsa parantezle birlikte. */
export function okulTamAd(o: Okul): string {
  return o.program ? `${o.ad} (${o.program})` : o.ad;
}

export function okulBul(id: string): Okul | undefined {
  return OKULLAR.find((o) => o.id === id);
}

/** Veride yer alan yıllar, büyükten küçüğe. */
export function tumYillar(): string[] {
  const set = new Set<string>();
  for (const o of OKULLAR) for (const y of Object.keys(o.puanlar)) set.add(y);
  return [...set].sort((a, b) => Number(b) - Number(a));
}

/** Bir okulun yılları, yeniden eskiye. */
export function okulYillari(o: Okul): string[] {
  return Object.keys(o.puanlar).sort((a, b) => Number(b) - Number(a));
}

/**
 * Listenin sıralama ve karşılaştırma yılı.
 *
 * 2026 verisi okulların yalnızca bir bölümünde var; listeyi ona göre kurmak
 * "kimi okul 2026, kimi 2025 puanıyla sıralanmış" gibi bir karışıklık yaratır.
 * Bu yüzden liste tek bir tam yıl üzerinden kuruluyor. Okul sayfasında
 * bütün yıllar (2026 dâhil) görünür.
 */
export const REFERANS_YIL = "2025";

/** En güncel taban puanı olan yıl — okul sayfasının özet kutuları için. */
export function guncelYil(o: Okul): string | null {
  for (const y of okulYillari(o)) {
    if (o.puanlar[y]?.taban != null) return y;
  }
  return null;
}

/** En güncel yüzdelik dilimi olan yıl (2026 yüzdelikleri açıklanmadı). */
export function guncelYuzdelikYili(o: Okul): string | null {
  for (const y of okulYillari(o)) {
    if (o.puanlar[y]?.yuzdelik != null) return y;
  }
  return null;
}
